(async () => {
  try {
    let dialogFields = this.getValue("dialog_update_field");
    const stockAdjustmentId = JSON.parse(this.getValue("stock_adjustment_id"));

    dialogFields = Object.entries(dialogFields).reduce((acc, [key, value]) => {
      if (value !== "" && value !== null && value !== undefined) {
        acc[key] = value;
      }
      return acc;
    }, {});

    console.log("dialogFields", dialogFields);
    console.log("stockAdjustmentId", stockAdjustmentId);

    await Promise.all(
      stockAdjustmentId.map(async (id) =>
        db.collection("stock_adjustment").doc(id).update(dialogFields)
      )
    );

    this.$message.success("Update successfully");
    await this.closeDialog("dialog_update_field");
    this.refresh();
  } catch (error) {
    this.$message.error(error);
  }
})();

