const callPostSAWorkflow = async (selectedRecords, aiData) => {
  if (aiData.acc_integration_type !== "No Accounting Integration") {
    await Promise.all(
      selectedRecords.map(async (item) => {
        await db
          .collection("stock_adjustment")
          .doc(item.id)
          .update({ posted_status: "Pending Post" });
      }),
    );
  }

  switch (aiData.acc_integration_type) {
    case "SQL Accounting":
      console.log("Calling SQL Accounting workflow");
      await this.runWorkflow(
        "1958732352162164738",
        { key: "value" },
        async (res) => {
          console.log("成功结果：", res);
          if (res.data.status === "running") {
            await this.runWorkflow(
              "1909088441531375617",
              { key: "value" },
              (res) => {
                console.log("成功结果：", res);
                this.$message.success("Stock Adjustment posted successfully.");
              },
              (err) => {
                this.hideLoading();
                console.error("失败结果：", err);
                throw new Error(
                  "Your SQL accounting software isn't connected. Check your network or ensure you're logged into your PC after a restart. Contact SuDu AI support if the issue persists.",
                );
              },
            );
          }
        },
        (err) => {
          console.log("失败结果：", err);

          this.hideLoading();
          throw new Error(
            "Your SQL accounting software isn't connected. Check your network or ensure you're logged into your PC after a restart. Contact SuDu AI support if the issue persists.",
          );
        },
      );
      break;

    case "AutoCount Accounting":
      console.log("Calling AutoCount Accounting workflow");
      await this.runWorkflow(
        "1996041757448597505",
        { sa_id: selectedRecords.map((item) => item.id) },
        (res) => {
          console.log("Workflow success", res);
        },
        (err) => {
          console.error("Workflow error", err);
          throw new Error(
            "Your AutoCount accounting software isn't connected. Check your network or ensure you're logged into your PC after a restart. Contact SuDu AI support if the issue persists.",
          );
        },
      );
      break;

    case "No Accounting Integration":
      break;

    case "SQL Accounting V2":
    case "AutoCount Accounting V2":
      this.$message.success("Stock Adjustment posted successfully.");
      this.refresh();
      this.hideLoading();
      await this.runWorkflow(
        "2013511169625042946",
        {
          agent_id: aiData.agent_id,
          task_type: "post_aj",
          payload: selectedRecords.map((item) => item.id),
          priority: "0",
        },
        async (res) => {
          console.log("成功结果：", res);
          // this.$message.success("Update Misc Issue successfully.");
        },
        (err) => {
          console.log("失败结果：", err);
          // this.hideLoading();
        },
      );
      break;
  }
};

(async () => {
  try {
    const unCompletedListID = "custom_z7cfnh6j";
    const allListID = "custom_y5ewf6w9";
    const tabUncompletedElement = document.getElementById("tab-tab_unposted");
    const organizationID = this.getVarGlobal("firstLvDeptId");
    this.showLoading("Post Stock Adjustment...");

    const activeTab = tabUncompletedElement?.classList.contains("is-active")
      ? "Uncompleted"
      : "All";

    let selectedRecords;

    selectedRecords = this.getComponent(
      activeTab === "Uncompleted" ? unCompletedListID : allListID,
    )?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);
    selectedRecords = selectedRecords.filter(
      (item) =>
        item.stock_adjustment_status === "Completed" &&
        item.posted_status !== "Pending Post" &&
        (item.adjustment_type === "Stock Count" ||
          item.adjustment_type === "Write Off"),
    );

    if (selectedRecords && selectedRecords.length > 0) {
      const saIN = selectedRecords.filter(
        (item) => item.adjustment_type === "Stock Count",
      );

      const saOUT = selectedRecords.filter(
        (item) => item.adjustment_type === "Write Off",
      );

      const resAI = await db
        .collection("accounting_integration")
        .where({ organization_id: organizationID })
        .get();

      if (resAI && resAI.data.length > 0) {
        const aiData = resAI.data[0];

        if (saIN.length > 0) {
          await callPostSAWorkflow(saIN, aiData);
        }

        if (saOUT.length > 0) {
          await callPostSAWorkflow(saOUT, aiData);
        }
      }

      await this.getComponent(
        activeTab === "Uncompleted" ? unCompletedListID : allListID,
      )?.$refs.crud.clearSelection();
      this.refresh();
      this.hideLoading();
    } else {
      this.hideLoading();
      this.$message.error("Please select at least one record.");
    }
  } catch (error) {
    console.error(error);
  }
})();

(async () => {
  const templateID = this.getValue(`dialog_print_template.template_id`);
  const stockAdjustmentID = this.getValue("stock_adjustment_id");
  const type = this.getValue(`dialog_print_template.type`);

  if (type === "Template") {
    window.open(
      `/sucode/openpage/${templateID}?stock_adjustment_id=${stockAdjustmentID}&name=Stock+Adjustment`
    );
  }

  this.setData({
    [`dialog_print_template.template_id`]: "",
    [`dialog_print_template.print_template_id`]: "",
    stock_adjustment_id: ''
  });

  this.closeDialog("dialog_print_template");
})();

(async () => {
  try {
    const allListID = "custom_y5ewf6w9";

    let selectedRecords;

    selectedRecords = this.getComponent(allListID)?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);

    if (selectedRecords && selectedRecords.length > 0) {
      const plantId = this.getVarSystem("deptIds").split(",")[0];
      let ids;

      ids = selectedRecords.map((item) => item.id);

      console.log("ids", ids);

      this.setData({
        stock_adjustment_id: ids.join(","),
      });

      const resTemplateAccess = await db
        .collection("print_template_access")
        .filter([
          {
            type: "branch",
            operator: "all",
            children: [
              {
                prop: "plant_id",
                operator: "in",
                value: plantId,
              },
              {
                prop: "doc_type",
                operator: "equal",
                value: "stock_adjustment",
              },
            ],
          },
        ])
        .get();

      if (!resTemplateAccess || resTemplateAccess.data.length === 0) {
        this.$message.error("No print template found.");
        return;
      } else if (resTemplateAccess && resTemplateAccess.data.length === 1) {
        const templateID = resTemplateAccess.data[0].print_template_id;

        window.open(
          `/sucode/openpage/${templateID}?stock_adjustment_id=${ids.join(
            ",",
          )}&name=Stock+Adjustment`,
        );
      } else if (resTemplateAccess && resTemplateAccess.data.length > 1) {
        await this.openDialog("dialog_print_template");
        setTimeout(() => {
          this.setData({
            [`dialog_print_template.template_id`]: "",
            [`dialog_print_template.print_template_id`]: "",
            [`dialog_print_template.type`]: "",
          });
          this.setOptionData(
            `dialog_print_template.print_template_id`,
            resTemplateAccess.data,
          );
        }, 50);
      }

      await this.getComponent(allListID)?.$refs.crud.clearSelection();
    } else {
      this.$message.error("Please select at least one record.");
    }
  } catch (error) {
    console.error(error);
  }
})();
